import indexJson from "../../data/creative-library.index.json";
import type { LibraryIndex } from "./types";
import { createLibraryLookup, type LibraryLookup } from "./lookup";

/** Server-side access to the imported Creative Library index (generated by scripts/import-creative-library.ts). */
const index = indexJson as unknown as LibraryIndex;
let lookup: LibraryLookup | null = null;

export function getLibraryIndex(): LibraryIndex {
  return index;
}

export function getLibrary(): LibraryLookup {
  if (!lookup) lookup = createLibraryLookup(index);
  return lookup;
}

/** Map of assetId → colours, used by validation contrast checks. */
export function assetColorsFor(ids: string[]): Record<string, string[]> {
  const lib = getLibrary();
  const out: Record<string, string[]> = {};
  for (const id of ids) {
    const a = lib.get(id);
    if (a) out[id] = a.colors;
  }
  return out;
}
